const visibleIds:string[] = [];
let cursor:string | undefined;
let feedReadError:string | null = null;
try {
  for (let page=0; page<5; page++) {
    const suffix = cursor ? '&cursor=' + encodeURIComponent(cursor) : '';
    const response = await api.get('/api/listings?fresh=1' + suffix);
    visibleIds.push(...response.data.items.map((item:{ id:string }) => item.id));
    const expected = external.data.receipts.map((item:{ publishedId:string | null }) => item.publishedId).filter(Boolean);
    if (!response.data.nextCursor || expected.every((id:string) => visibleIds.includes(id))) break;
    cursor = response.data.nextCursor;
  }
} catch { feedReadError = 'No se pudo comprobar la lectura del feed.'; }

